import{_ as r,o as p,c as o,a0 as i,j as e,a as t}from"./chunks/framework.BsWcg17L.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"mpc.md","filePath":"mpc.md"}'),m={name:"mpc.md"};function n($,a,l,_,d,s){return p(),o("div",null,[...a[0]||(a[0]=[i('<h2 id="model-predictive-control-mpc" tabindex="-1">Model Predictive Control (MPC) <a class="header-anchor" href="#model-predictive-control-mpc" aria-label="Permalink to &quot;Model Predictive Control (MPC)&quot;">​</a></h2><ul><li>Linear state-space model:</li></ul><p>$$ x_{k+1} = A x_k + B u_k $$<br> where<br> $$ A \\in \\mathbb{R}^{nxn} $$<br> $$ B \\in \\mathbb{R}^{nxm} $$<br> $$ x_{k} \\in \\mathbb{R}^{nx1} $$<br> $$ u_{k} \\in \\mathbb{R}^{mx1} $$</p><ul><li><p>Quadratic cost on states and inputs:<br> $$ J = \\sum_{k=0}^{N}\\left(x_k^\\top Q x_k+u_k^\\top R u_k\\right) $$ where<br> $$ Q \\succeq 0, \\qquad $$ $$ R \\succ 0, \\qquad $$<br> are weighting matrices for states and control effort.</p></li><li><p>Box constraints (lower and upper bounds) on control inputs:<br> $$ u_{lb} &lt;= u_{k} &lt;= u_{ub}<br> $$</p></li><li><p>Optimization solved using QP algorithms</p></li><li><p>Lifted matrices dictated by prediction horizon</p></li></ul><p>Lifted system matrices form when prediction horizon is set to N:</p><p>$$ X_k = A_{lifted} x_k + B_{lifted} U_k $$</p>',6),e("p",null,[t("$$ X_k = \\begin{bmatrix} \\hat{x}"),e("em",{"k+1|k":""},"{k|k} \\ \\hat{x}"),t(" \\ \\vdots \\ \\hat{x}_{k+N|k} \\end{bmatrix} \\in \\mathcal{X}^{N+1} \\subseteq \\mathbb{R}^{n(N+1)}, \\quad $$")],-1),e("p",null,[t("$$ U_k = \\begin{bmatrix} \\hat{u}"),e("em",{"k+1|k":""},"{k|k} \\ \\hat{u}"),t(" \\ \\vdots \\ \\hat{u}_{k+N-1|k} \\end{bmatrix} \\in \\mathcal{U}^{N} \\subseteq \\mathbb{R}^{mN} $$")],-1),i('<p>$$ A_{lifted} = \\begin{bmatrix} I \\ A \\ A^2 \\ \\vdots \\ A^N \\end{bmatrix} \\in \\mathbb{R}^{n(N+1)\\times n} $$</p><p>$$ B_{lifted} = \\begin{bmatrix} 0 &amp; 0 &amp; \\cdots &amp; 0 \\ B &amp; 0 &amp; \\cdots &amp; 0 \\ AB &amp; B &amp; \\cdots &amp; 0 \\ \\VDTs &amp; \\vdots &amp; \\ddots &amp; \\vdots \\ A^{N-1}B &amp; A^{N-2}B &amp; \\cdots &amp; B \\end{bmatrix} \\in \\mathbb{R}^{n(N+1)\\times m(N+1)} $$</p><p>The Quadratic Programming problem is of form:</p><p>$$ U_k^* = \\arg\\min_{U_k}; X_k^\\top \\tilde{Q} X_k + U_k^\\top \\tilde{R} U_k $$ subject to $$ X_k = A_{lifted} x_k + B_{lifted} U_k $$</p><p>$$ U_k \\in \\mathcal{U}_{ad}(x_k) $$ with $$ \\tilde{Q} = \\begin{bmatrix} Q &amp; &amp; \\ &amp; \\ddots &amp; \\ &amp; &amp; Q_f \\end{bmatrix} \\in \\mathbb{R}^{n(N+1)\\times n(N+1)}, \\qquad \\tilde{R} = \\begin{bmatrix} R &amp; &amp; \\ &amp; \\ddots &amp; \\ &amp; &amp; R \\end{bmatrix} \\in \\mathbb{R}^{mN\\times mN}<br> $$</p><p>The QP problem can be reduced to the following form when $X_k$ is substituted to the cost function.</p><p>$$ U_k^* = \\arg\\min_{U_k}; U_k^\\top(B_{lifted}^\\top \\tilde{Q}B_{lifted} + \\tilde{R})U_k</p><ul><li>2x_k^\\top A_{lifted}^\\top B_{lifted} U_k</li><li>x_k^\\top A_{lifted}^\\top \\tilde{Q}A_{lifted} x_k $$ subject to $$ U_k \\in \\mathcal{U}_{ad}(x_k) $$</li></ul><h3 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h3><p>Michael Fink (2021).<br> Implementation of Linear Model Predictive Control — Tutorial.<br><a href="https://arxiv.org/abs/2109.11986" target="_blank" rel="noreferrer">https://arxiv.org/abs/2109.11986</a></p><hr><hr><hr><h2 id="robust-model-predictive-control-rmpc" tabindex="-1">Robust Model Predictive Control (RMPC) <a class="header-anchor" href="#robust-model-predictive-control-rmpc" aria-label="Permalink to &quot;Robust Model Predictive Control (RMPC)&quot;">​</a></h2><ul><li>Linear state-space model</li><li>Quadratic cost on states and inputs</li><li>Box constraints on control inputs</li><li>Optimization solved using LMI</li></ul><p>$$ x_{k+1}=Ax_k+Bu_k $$</p><p>$$ u_k=Lx_k $$</p><p>$$ J = \\sum_{k=0}^{\\infty} \\left( x_k^\\top Q x_k + u_k^\\top R u_k \\right) $$</p><p>$$ Q \\succeq 0, \\qquad R \\succ 0 $$</p><p>$$ Y = LQ_U $$</p><p>The LMI formulation of the problem:</p><p>$$ \\min_{Q_U,Y,X_U,\\gamma} \\gamma $$</p><p>subject to</p><p>$$ \\begin{bmatrix} 1 &amp; x_k^\\top \\ x_k &amp; Q_U \\end{bmatrix} \\succeq 0 $$</p><p>$$ \\begin{bmatrix} X_U &amp; Y \\ Y^\\top &amp; Q_U \\end{bmatrix} \\succeq 0 $$</p><p>$$ \\begin{bmatrix} Q_U &amp; Q_UA^\\top + Y^\\top B^\\top &amp; Q_UQ^{1/2} &amp; Y^\\top R^{1/2} \\ AQ_U + BY &amp; Q_U &amp; 0 &amp; 0 \\ Q^{1/2}Q_U &amp; 0 &amp; \\gamma I &amp; 0 \\ R^{1/2}Y &amp; 0 &amp; 0 &amp; \\gamma I \\end{bmatrix} \\succeq 0 $$</p><p>Where the box constraint:</p><p>$$ |u_{k,j}| \\le u_{j,\\max} $$</p><p>is implemented as</p><p>$$ (X_U)<em>{jj} \\le u</em>{j,\\max}^2 $$</p><p>The feedback gain is recovered from</p><p>$$ L = YQ_U^{-1} $$</p><p>RMPC control input:</p><p>$$ u_k=Lx_k $$</p><h3 id="reference-1" tabindex="-1">Reference <a class="header-anchor" href="#reference-1" aria-label="Permalink to &quot;Reference&quot;">​</a></h3><p>Kothare, M. V., Balakrishnan, V., &amp; Morari, M. (1996).<br><strong>Robust constrained model predictive control using linear matrix inequalities</strong>.<br><em>Automatica</em>, 32(10), 1361–1379.<br> DOI: 10.1016/0005-1098(96)00063-5</p><hr><hr><hr>',39)])])}const u=r(m,[["render",n]]);export{b as __pageData,u as default};
